j:if.g2:evaluate:
   var now = "";
	   now = gs.nowDateTime();
	   start_time = now;
	   end_time = now;
	   max_rows = "1000";


  var logFile =  new GlideLogFileReader();
  if (time_diff) {
	 logFile.setTimeRange(start_time, time_diff);
  } else {
	 logFile.setStartTime(start_time);
	 if (end_time) {
		logFile.setEndTime(end_time);
		}
  }

  if (max_rows)
	 logFile.setMaxRows(max_rows);

  var session_message = "";
  if (typeof filter_session == 'undefined' || filter_session == '') 
	 filter_session = 'null';

  if (typeof match_session == 'undefined') 
	 match_session = '';

  logFile.setSession(filter_session);
  logFile.setMatchSession(match_session);
  logFile.setLevel(level);
  logFile.setMessage(message);
  logFile.setThread(filter_thread);
  var system_start_time = logFile.getStartTime();
  var system_end_time = logFile.getEndTime();
  logFile.open();

